const selected = String($('Webhook').first().json.body.chairman || '').replace(/\s+/g, '').trim();
function text(value) {
  if (value == null) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return value.map(text).filter(Boolean).join('');
  if (value.plain_text) return String(value.plain_text);
  if (value.name) return String(value.name);
  if (value.title) return text(value.title);
  if (value.rich_text) return text(value.rich_text);
  if (value.select) return text(value.select);
  return '';
}
function candidateName(json) {
  if (json.name) return text(json.name);
  const props = json.properties || {};
  const titleProp = Object.values(props).find((value) => value?.type === 'title');
  return text(titleProp);
}
function toFiniteNumber(value) {
  if (value == null || value === '') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}
function voteCount(json) {
  const props = json.properties || {};
  for (const value of Object.values(props)) {
    if (value?.type === 'number') return toFiniteNumber(value.number) ?? 0;
  }
  for (const [key, value] of Object.entries(json)) {
    if (key === 'id' || key === 'url' || key === 'name') continue;
    if (typeof value === 'number') return value;
    if (key.startsWith('property_')) {
      const number = toFiniteNumber(value);
      if (number != null) return number;
    }
    if (value?.number != null) {
      const number = toFiniteNumber(value.number);
      if (number != null) return number;
    }
  }
  return 0;
}
const found = $input.all().find((item) => candidateName(item.json).replace(/\s+/g, '').trim() === selected);
if (!found) throw new Error('Candidate not found for chairman: ' + selected);
found.json.currentVotes = voteCount(found.json);
found.json.nextVotes = found.json.currentVotes + 1;
return [found];

